// === BEELINE: WhatsApp with Conversation Memory ===
// Receives: bridge payload with conversationHistory + vendor persona
// Sends: Groq with full context

console.log('Webhook payload:', JSON.stringify($json, null, 2));

const payload = $json;
const userMessage = payload.message || 'Hello';
const conversationHistory = Array.isArray(payload.conversationHistory) ? payload.conversationHistory : [];
const vendor = payload.vendor && typeof payload.vendor === 'object' ? payload.vendor : {};

const businessName = vendor.name || payload.businessName || 'Our Business';
const personalityTone = vendor.personalityTone || 'friendly';
const systemPromptOverride = vendor.systemPromptOverride;

const isFirstMessage = conversationHistory.length === 0;

console.log(`History length: ${conversationHistory.length}, isFirstMessage: ${isFirstMessage}`);

// Build system prompt
let systemPrompt;
if (systemPromptOverride) {
  systemPrompt = systemPromptOverride;
} else {
  systemPrompt = `You are a helpful customer service AI for ${businessName}.
Personality: ${personalityTone}

IMPORTANT:
- REMEMBER everything discussed in this conversation
- REFERENCE previous messages when relevant
- Keep responses under 100 words
- Be personable and helpful

${isFirstMessage ? 'This is the customer\'s first message - give a warm welcome.' : 'This is a follow-up message - engage with the conversation naturally.'}`;
}

// Build messages array WITH conversation history
const messages = [{ role: 'system', content: systemPrompt }];

// Add all previous messages from history
if (Array.isArray(conversationHistory) && conversationHistory.length > 0) {
  conversationHistory.forEach(msg => {
    if (msg.role && msg.content) {
      messages.push({ role: msg.role, content: msg.content });
    }
  });
}

// Add the current user message
messages.push({ role: 'user', content: userMessage });

console.log('Messages for Groq:', JSON.stringify(messages, null, 2));

return {
  json: {
    model: 'llama-3.3-70b-versatile',
    messages: messages,
    temperature: 0.7,
    max_tokens: 500,
    vendorId: payload.vendorId,
    customerId: payload.customerId,
    debug: { historyLength: conversationHistory.length, isFirstMessage }
  }
};
